:#8190a4;font-size:11px;margin-top:18px}.roles-hint{padding:13px;background:#f2f7fd;border:1px solid #e0edfc;border-radius:9px;color:#536b87;font-size:12px;line-height:1.9}.roles-toast{position:fixed;bottom:22px;left:22px;background:#152d4d;color:#fff;padding:12px 18px;border-radius:10px;z-index:20}.roles-module-icon-blue{color:#1674ed;background:#e4efff!important}.roles-module-icon-green{color:#0ba56b;background:#e0f8eb!important}.roles-module-icon-red{color:#ed4b55;background:#ffebed!important}.roles-module-icon-purple{color:#8b3df1;background:#f0e5ff!important}.roles-module-icon-teal{color:#089c96;background:#dcf8f5!important}.roles-module-icon-orange{color:#e99013;background:#fff0d9!important}.roles-module-icon-slate{color:#5e6d80;background:#edf1f5!important}@media(max-width:1050px){.roles-layout{grid-template-columns:1fr}.roles-editor,.roles-list-panel{grid-column:1;grid-row:auto}.roles-editor{order:1}.roles-list-panel{order:2}}@media(max-width:650px){.roles-page-title{align-items:flex-start;flex-wrap:wrap}.roles-page-title h1{font-size:20px}.roles-add-btn{width:100%;margin:0}.roles-panel{padding:14px 11px}.roles-fields{grid-template-columns:1fr}.roles-status{display:none}.roles-perm-heading{align-items:flex-start;flex-direction:column}.roles-bulk{width:100%}.roles-bulk .btn{flex:1;white-space:normal}.roles-footer{align-items:stretch;flex-direction:column}.roles-footer>div .btn{flex:1}.roles-permission-grid{grid-template-columns:1fr}}
